content.css:
/* ========================================================================== */
/* BFUSION Resource Efficiency Breakdown — Structural Layout                  */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  color: #242424;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-reb {
  display: flex;
  flex-direction: column;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
/* Header bar (title + subtitle + info button) */
.reb-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 16px 6px 16px;
  border-bottom: 1px solid #E5E7EB;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  position: relative;
}
.reb-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.reb-header__title {
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.reb-header__subtitle {
  margin-top: 2px;
  color: #6C757D;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.reb-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #6C757D;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
}
.reb-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
}
.reb-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 280px;
  max-width: calc(100% - 24px);
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: #242424;
  line-height: 1.45;
}
.reb-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.reb-header__info-pop ul li {
  margin: 3px 0;
  color: #6C757D;
}
.reb-info-pop__title {
  font-weight: 700;
  color: #242424;
  margin-bottom: 4px;
}
.reb-info-pop__desc {
  color: #6C757D;
}
/* Body row: chart + insight strip + insight panel */
.reb-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
}
.reb-chart-col {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  overflow: hidden;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  display: block;
  background: #ffffff;
}
/* Bar hover effect */
.bfusion-chart-wrap svg rect {
  transition: opacity 0.2s ease;
}
/* ========================================================================== */
/* Insight Panel (right-side) — collapsed strip + expanded panel             */
/* ========================================================================== */
.reb-insight-strip {
  flex: 0 0 auto;
  width: 24px;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  color: #6C757D;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.reb-insight-strip__arrow {
  font-size: 11px;
  color: var(--reb-insight-accent, #E8612A);
  line-height: 1;
}
.reb-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 2px;
  font-weight: 600;
  color: #6C757D;
  text-transform: uppercase;
}
.reb-insight-strip:hover,
.reb-insight-strip:focus {
  background: #FFFFFF;
  color: #242424;
  outline: none;
}
.reb-insight-panel {
  flex: 0 0 250px;
  max-width: 280px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-left: 1px solid #E5E7EB;
  display: flex;
  flex-direction: column;
  padding: 12px 12px 16px 12px;
  overflow-y: auto;
  font-size: var(--reb-insight-font, 11px);
  color: #242424;
  gap: 10px;
}
.reb-insight-panel__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--reb-insight-accent, #E8612A);
}
.reb-insight-panel__title {
  font-size: var(--reb-insight-header-font, 12px);
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.2px;
}
.reb-insight-panel__subtitle {
  font-size: calc(var(--reb-insight-font, 11px) - 1px);
  color: #6C757D;
}
.reb-insight-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.reb-insight-panel__healthbar {
  display: flex;
  flex-direction: row;
  height: 8px;
  width: 100%;
  border-radius: 4px;
  overflow: hidden;
  background: #E5E7EB;
  margin-top: 2px;
}
.reb-insight-panel__healthbar-fill {
  height: 100%;
  transition: width 0.25s ease;
}
.reb-insight-panel__section {
  margin-top: 4px;
}
.reb-insight-panel__section-title {
  font-weight: 600;
  color: #6C757D;
  font-size: calc(var(--reb-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.reb-insight-panel__smart {
  margin: 0;
  padding-left: 16px;
}
.reb-insight-panel__smart li {
  margin: 4px 0;
  line-height: 1.4;
  color: #242424;
}
.reb-insight-panel__smart strong {
  font-weight: 700;
}
.reb-insight-panel__smart em {
  font-style: italic;
  color: #6C757D;
}
.reb-insight-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.reb-insight-panel__list li {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 4px;
  margin-bottom: 2px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
}
.reb-insight-panel__dot {
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.95);
}
.reb-insight-panel__name {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.reb-insight-panel__val {
  flex: 0 0 auto;
  font-weight: 600;
  color: #242424;
  font-variant-numeric: tabular-nums;
}
.reb-kpi {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-left: 3px solid var(--reb-kpi-color, #E8612A);
  border-radius: 6px;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.reb-kpi:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);
}
.reb-kpi__value {
  font-size: calc(var(--reb-insight-font, 11px) + 4px);
  font-weight: 700;
  color: var(--reb-kpi-color, #242424);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}
.reb-kpi__label {
  font-size: calc(var(--reb-insight-font, 11px) - 1px);
  color: #6C757D;
}
/* Insight panel visibility states */
.reb-body--insight-collapsed .reb-insight-panel {
  display: none;
}
.reb-body--insight-hidden .reb-insight-panel,
.reb-body--insight-hidden .reb-insight-strip {
  display: none;
}
/* ========================================================================== */
/* Responsive width classes                                                   */
/* ========================================================================== */
.reb-medium .reb-insight-panel {
  flex-basis: 220px;
}
.reb-narrow .reb-insight-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 0;
  width: 240px;
  z-index: 25;
  box-shadow: -6px 0 18px rgba(15, 23, 42, 0.1);
}
.reb-narrow .reb-header__title {
  font-size: 12px !important;
}
/* ========================================================================== */
/* Landing Page                                                               */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* Fade-In Animation                                                          */
/* ========================================================================== */
@keyframes bfusion-fadein-anim {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.bfusion-chart-wrap.bfusion-fadein {
  animation: bfusion-fadein-anim var(--bfusion-fadein-duration, 600ms) ease-out forwards;
}
/* ========================================================================== */
/* License Badge                                                               */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State                                                            */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
